const Pill = ({ children, tone = "info" }: { children: ReactNode; tone?: Tone }) => <span className={`rf-pill rf-${tone}`}>{children}</span>;
const CardTitle = ({ eyebrow, title, action }: { eyebrow: string; title: string; action?: ReactNode }) => (
  <div className="rf-card-title"><div><span>{eyebrow}</span><h3>{title}</h3></div>{action}</div>
);

