const RiskNetwork = ({ onToast }: { onToast: (s: string) => void }) => <article className="rf-card"><CardTitle eyebrow="DEPENDENCY RISK" title="Concentração e dependências" /><div className="rf-network"><button className="source" onClick={() => onToast("HMR-882 aberto no M3")}>HMR-882<small>Inundação P90</small></button><i>→</i><button>C17<small>74% capacidade</small></button><i>→</i><button>Pelotização<small>12,4 kt</small></button><i>→</i><button className="target">R-021<small>P90 R$ 12,7 mi</small></button></div><div className="rf-concentration"><span>Contribuição por perigo</span>{[["Inundação",38],["Vento",21],["Água",17],["Calor",9],["Outros",15]].map(([name,value]) => <div key={name}><b>{name}</b><i><em style={{width:`${value}%`}} /></i><strong>{value}%</strong></div>)}</div><div className="rf-concentration"><span>Concentração por ativo</span>{[["C17",14],["SE-04",12],["D-04",11]].map(([name,value]) => <div key={name}><b>{name}</b><i><em style={{width:`${Number(value)*5}%`}} /></i><strong>{value}%</strong></div>)}</div></article>;

