const AppetiteView = ({ onGovernance, onToast }: { onGovernance: () => void; onToast: (s: string) => void }) => <><div className="rf-view-heading"><div><span>RISK APPETITE FRAMEWORK</span><h2>Apetite, tolerância e limite</h2><p>Limites corporativos do M7 não substituem limiares técnicos de ativos do M4.</p></div><button className="rf-link-button" onClick={onGovernance}>Políticas e autoridade M11 ↗</button></div><section className="rf-grid rf-grid-3"><article className="rf-card rf-appetite-breach"><span>INTERRUPÇÃO DE PRODUÇÃO</span><strong>14 h/ano</strong><small>exposição atual</small><div><b>Apetite</b><em>BAIXO</em></div><div><b>Tolerância</b><em>8 h/ano</em></div><Pill tone="critical">BREACH · +6 HORAS</Pill></article><article className="rf-card rf-span-2"><CardTitle eyebrow="APPETITE MONITOR" title="Exposição × tolerância × limite" /><div className="rf-appetite-bars">{[["Interrupção produção",14,8,12],["Perda financeira",4.8,5,10],["Água",31,25,45],["Contrato",.28,.5,1],["Social não financeiro",4,3,5]].map(([a,current,tol,limit])=><div key={a as string}><span>{a}</span><div><i className="tolerance" style={{left:`${Number(tol)/Number(limit)*100}%`}} /><em style={{width:`${Math.min(100,Number(current)/Number(limit)*100)}%`}} /></div><b>{current} / {tol}</b></div>)}</div></article></section><section className="rf-card"><CardTitle eyebrow="BREACH WORKFLOW" title="R-021 · resposta requerida" /><div className="rf-breach-flow">{["Detectado","Owner notificado","Tratamento proposto","Autoridade revisa","Aceitar / reduzir","Monitorar até expiração"].map((x,i)=><div key={x} className={i<2?"done":""}><i>{i<2?"✓":i+1}</i><span>{x}</span></div>)}</div><div className="rf-actions"><button onClick={()=>onToast("Justificativa e alternativas anexadas ao breach R-021")}>Anexar justificativa</button><button className="primary" onClick={()=>onToast("Workflow de aceite enviado à autoridade competente; expiração obrigatória")}>Solicitar aceite temporário</button></div></section></>;

