const AgentRail = ({ onAgents, onToast }: { onAgents: () => void; onToast: (s: string) => void }) => <section className="rf-card rf-agent-rail"><CardTitle eyebrow="LIVE AGENT FEED" title="Orquestração em tempo real" action={<button className="rf-text-button" onClick={onAgents}>15 agentes · abrir central</button>} /><div>{riskBaseFeed.slice(0,4).map((item,i)=><button key={item.agent} onClick={()=>onToast(`${item.agent}: trace ${i+1} aberto`)}><i className={`rf-bg-${item.type}`}>AI</i><span><b>{item.agent}</b><small>{item.text}</small></span><time>18:5{i}:0{4+i}</time></button>)}</div></section>;

export function RiskModule(props: RiskModuleProps) {
  const content = useMemo(() => {
    if (props.subview === "Situação") return <SituationView {...props} />;
    if (["Registro de Riscos", "Mapa"].includes(props.subview)) return <RegisterView {...props} />;
    if (["Risco Físico", "Agudo", "Crônico", "Ambiental e Social"].includes(props.subview)) return <PhysicalView {...props} />;
    if (["Financeiro", "Perdas", "Contratos", "Seguros"].includes(props.subview)) return <FinanceView {...props} />;
    if (["Stress Tests", "NGFS", "Transição"].includes(props.subview)) return <ScenarioView {...props} />;
    if (["Adaptação", "Risco Residual", "Apetite", "Tratamentos"].includes(props.subview)) return <TreatmentView {...props} />;
    if (props.subview === "Disclosure") return <DisclosureView {...props} />;
    if (props.subview === "Histórico") return <HistoryView {...props} />;
    if (props.subview === "Agentes & Integrações") return <AgentsView {...props} />;
    return <ReportsView {...props} />;
  }, [props]);

  return <main className="risk-module" data-profile={props.profile} data-horizon={props.horizon}>
    <div className="rf-runtime-banner"><span className="rf-live-dot" /><b>RISK ENGINE</b><span>RS-041 · R-021 · FI-021</span><i /> <small>{props.stage.label} · {props.stage.note}</small><Pill tone={props.stage.tone}>{props.stage.time ?? "LIVE"}</Pill></div>
    {content}
  </main>;
}
